// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.deal(address(c), 1 ether);
        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        // General rule: the call succeeds if and only if the caller is the owner
        // (the deployer, i.e. this test contract); afterwards the contract is
        // destroyed and its balance is gone.
        assertTrue(ok == (actor == address(this)) && (!ok || address(c).balance == 0));
    }
}

