pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1 ether, 100 ether);

        // owner (this test contract, deployer) triggers the suicide
        c.sudicideAnyone();

        // After destruction, the address has no code, so a plain call with
        // value and empty data must SUCCEED. The mutant keeps the code and
        // has no receive/fallback, so the same call REVERTS.
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok, "destroyed contract should accept value-carrying plain calls");
    }
}

