contract InvMutTest {
    C c;
    constructor(C _c) {
        // The counterexample passes this very contract as _c, making this test
        // contract both the target and the owner of C, so sudicideAnyone succeeds.
        // Exclude that input: c must be a distinct contract (not deployed by us).
        require(address(_c) != address(this));
        c = _c;
    }
    function run(uint x) public payable {
        require(true);
        bool reverted;
